constexpr uint32_t kHeroState = 0x2084u;
constexpr uint32_t kHeroFrameMode = 0x20B3u;
constexpr uint32_t kHeroVehicleMode = 0x20A4u;
constexpr uint32_t kHeroSlot0 = 0x1090u;
