Options s_options;
VrOptions s_vr;

// The arms' moves as they are played: the launcher's (or VR Controls') switch, but off with Arm moves on Buttons.
bool real_wrench() { return s_options.swing_wrench && !s_vr.button_moves; }
bool real_throws() { return s_options.throw_by_hand && !s_vr.button_moves; }
bool real_ledges() { return s_options.grab_ledges && !s_vr.button_moves; }
bool real_swim() { return s_options.swim_strokes && !s_vr.button_moves; }
XrSettings s_xr;

// How a cutscene is seen (the launcher's "cutscenes": eyes, vr, screen; VR Options' Cutscenes row; X in a scene):
// through his eyes, in VR around you from the game's camera, or on a screen. A cutscene's own: play keeps the View row's.
constexpr int kSceneViewEyes = 0, kSceneViewVr = 1, kSceneViewScreen = 2, kSceneViewCount = 3;
const char* const kSceneViewNames[kSceneViewCount] = {"through his eyes", "in VR", "on a screen"};
int scene_view_now() {
    return !s_options.scenes_in_vr ? kSceneViewScreen : s_options.scene_eyes ? kSceneViewEyes : kSceneViewVr;
}
void set_scene_view(int view) {
    s_options.scenes_in_vr = view != kSceneViewScreen;
    s_options.scene_eyes = view == kSceneViewEyes;
}

// The HUD Height (VR Hands), metres up.
float hud_lift() { return static_cast<float>(s_vr.hud_height) / 100.0f; }
// How far the view stands above his own eyes: Play position's, View height's and Feet on the floor's.
float view_lift() { return static_cast<float>(s_vr.view_height) / 100.0f + s_floor_lift; }
bool s_started = false;
bool s_failed = false;
std::string s_status_file;

Rig s_rig;
FrameInfo s_frame;
uint64_t s_tick = 0;

// RAC-Board ("RAC-Board" below; vr/src/board.h): whether it is loaded and its buttons, whether he rides it, the reach
// behind the back that gets him on and off, and the view's turn with the board.
struct JetBoard {
    bool looked = false;
    bool loaded = false;
    BoardButtons buttons;
    bool motion_seen = true;  // the game's own update of him ran since the last tick (update_motion_input)
    int missed = 0;           // ticks in a row it did not
    bool riding = false;
    // RAC-Board's "Weapons on the board" (the Quest build's patch of it, patches/rac-board): weapons, gadgets and the
    // wrench in his hand while he rides, and the board back under him as a Swingshot swing or pull ends. False for a
    // RAC-Board without it.
    bool weapons = false;
    uint64_t left_at = 0;     // the tick the last ride ended
    bool swung = false;       // he swung or was pulled on the Swingshot since: RAC-Board puts him back on the board as it ends
    uint64_t swing_seen_at = 0;  // the last tick in one of the Swingshot's states, while swung
    bool behind[2] = {};      // each hand behind the back
    bool click_was[2] = {};
    bool owned[2] = {};       // that stick's click was the board's: nothing else sees it until let go
    int toggle_ticks = 0;     // the board's button pressed for these ticks yet
    uint64_t toggled_at = 0;  // the tick it was last pressed: a ride starts only soon after a press
    bool toggled = false;
    BoardFollow follow;
    Quat body{};              // his body's turn from his stance (BoardFollow's), before board_view_turn
    BoardView view;
    Vec3 pivot{};             // his middle (the pelvis) in the frame: the view's turn is about it
};
JetBoard s_jet;

bool s_have_frame = false;
bool s_frame_open = false;
